document.addEventListener("DOMContentLoaded", () => {
  const cartBtn = document.getElementById("cartBtn");
  const wandBtn = document.getElementById("wandBtn");
  const plusBtn = document.getElementById("plusBtn");
  const panel = document.getElementById("similarPanel");
  const popup = document.querySelector(".floating-popup");
  const cards = document.querySelectorAll(".card");

  // -------------------
  // HELPER: collapse both buttons
  // -------------------
  function collapseButtons() {
    cartBtn.classList.remove("expanded");
    wandBtn.classList.remove("expanded");
  }

  // -------------------
  // HOVER LOGIC → simultaneous contract/expand
  // -------------------
  cartBtn.addEventListener("mouseenter", () => {
    wandBtn.classList.remove("expanded"); // contract wandBtn
    cartBtn.classList.add("expanded");    // expand cartBtn
  });

  wandBtn.addEventListener("mouseenter", () => {
    cartBtn.classList.remove("expanded"); // contract cartBtn
    wandBtn.classList.add("expanded");    // expand wandBtn
  });

  popup.addEventListener("mouseleave", () => {
    collapseButtons(); // collapse both when mouse leaves popup
  });

  // -------------------
  // PLUS BUTTON → toggle panel + rotation
  // -------------------
  plusBtn.addEventListener("click", () => {
    const isActive = plusBtn.classList.toggle("active");
    panel.classList.toggle("open", isActive);

    if (!isActive) collapseButtons(); // collapse buttons when panel closed
  });

  // -------------------
  // CLICK OUTSIDE → close everything
  // -------------------
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".floating-popup") && !e.target.closest(".similar-panel")) {
      collapseButtons();
      plusBtn.classList.remove("active");
      panel.classList.remove("open");
    }
  });

  // -------------------
  // LOTTIE BACKGROUND
  // -------------------
  if (popup && !popup.querySelector(".lottie-bg")) {
    const lottieDiv = document.createElement("div");
    lottieDiv.className = "lottie-bg";
    popup.prepend(lottieDiv);

    const animation = lottie.loadAnimation({
      container: lottieDiv,
      renderer: "svg",
      loop: true,
      autoplay: true,
      path: "https://cdn.prod.website-files.com/65cd9d695e36c5b54d75b895/6913042f1c59e4aae08071c0_Confetti.json"
    });

    animation.setSpeed(0.4);
  }

  // -------------------
  // CARD HOVER OPACITY
  // -------------------
  cards.forEach(card => {
    card.addEventListener("mouseenter", () => {
      cards.forEach(c => c.style.opacity = "0.5");
      card.style.opacity = "1";
    });

    card.addEventListener("mouseleave", () => {
      cards.forEach(c => c.style.opacity = "1");
    });
  });

});

