// Convert hex and rgba colors to OKLCH
// Using CSS Color Level 4 conversion via sRGB → linear-sRGB → XYZ → OKLab → OKLCH

function hexToRgb(hex) {
  hex = hex.replace('#', '');
  if (hex.length === 3) hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
  return [parseInt(hex.slice(0,2),16)/255, parseInt(hex.slice(2,4),16)/255, parseInt(hex.slice(4,6),16)/255];
}

function srgbToLinear(c) {
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

function linearToOklab(r, g, b) {
  let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
  let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
  let s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
  l = Math.cbrt(l); m = Math.cbrt(m); s = Math.cbrt(s);
  return [
    0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s
  ];
}

function oklabToOklch(L, a, b) {
  const C = Math.sqrt(a*a + b*b);
  let H = Math.atan2(b, a) * 180 / Math.PI;
  if (H < 0) H += 360;
  return [L, C, H];
}

function hexToOklch(hex) {
  const [r, g, b] = hexToRgb(hex);
  const [lr, lg, lb] = [srgbToLinear(r), srgbToLinear(g), srgbToLinear(b)];
  const [L, a, bv] = linearToOklab(lr, lg, lb);
  const [l, c, h] = oklabToOklch(L, a, bv);
  return `oklch(${(l*100).toFixed(2)}% ${c.toFixed(4)} ${h.toFixed(2)})`;
}

function rgbaToOklch(r, g, b, a) {
  const [lr, lg, lb] = [srgbToLinear(r/255), srgbToLinear(g/255), srgbToLinear(b/255)];
  const [L, av, bv] = linearToOklab(lr, lg, lb);
  const [l, c, h] = oklabToOklch(L, av, bv);
  if (a < 1) {
    return `oklch(${(l*100).toFixed(2)}% ${c.toFixed(4)} ${h.toFixed(2)} / ${a})`;
  }
  return `oklch(${(l*100).toFixed(2)}% ${c.toFixed(4)} ${h.toFixed(2)})`;
}

