/* Panel body staggered entrance */
@keyframes scFadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes scSlideIn {
  from { opacity: 0; transform: translateX(20px); }
  to   { opacity: 1; transform: translateX(0); }
}

.sc-panel-body h3,
.sc-panel-body > p,
.sc-panel-body .sc-cta {
  opacity: 0;
}
.sc-panel-body .check-list li {
  opacity: 0;
}

.sc-panel.is-animating .sc-panel-body h3 {
  animation: scFadeIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: 0.15s;
}
.sc-panel.is-animating .sc-panel-body > p {
  animation: scFadeIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: 0.35s;
}
.sc-panel.is-animating .sc-panel-body .check-list li {
  animation: scSlideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc(1s + var(--li, 0) * 0.1s);
