.section-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 20px;
}

.hero-stats {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 48px;
}
.stat-number {
  font-size: 48px;
  font-weight: 800;
  line-height: 1;
  color: var(--accent);
}
.stat-plus, .stat-unit {
  font-size: 32px;
  color: var(--accent);
}
.stat-label {
  font-size: 14px;
  color: oklch(100% 0 none / 0.5);
  margin-top: 4px;
}
.stat-divider {
  width: 1px;
  height: 60px;
  background: oklch(100% 0 none / 0.15);
}

/* ===== ABOUT SECTION ===== */
#about {
  background: var(--cream);
  padding: var(--section-pad);
}
.about-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.about-img {
  height: 400px;
  border-radius: var(--radius);
  overflow: hidden;
}
.about-text h2 {
  font-size: clamp(32px, 4vw, 44px);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1px;
  color: var(--cobalt);
  margin-bottom: 20px;
}
.about-text p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.7;
  margin-bottom: 32px;
}

/* ===== STATS SECTION ===== */
#stats {
  background: var(--cream);
  padding: var(--section-pad);
}
.stats-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 64px;
}
.stats-header h2 {
  font-size: clamp(32px, 4vw, 48px);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1px;
  color: var(--cobalt);
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.stats-card {
  text-align: center;
  padding: 32px 16px;
}
.stats-card .big-number {
  font-size: clamp(48px, 5vw, 64px);
  font-weight: 800;
  color: var(--dark);
  line-height: 1;
  margin-bottom: 8px;
}
.stats-card .big-number span {
  color: var(--accent);
}
.stats-card h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--dark);
}
.stats-card p {
  font-size: 13px;
  color: var(--gray-600);
  line-height: 1.6;
}

/* ===== SUSTAINABILITY SECTION ===== */
#sustainability {
  background: linear-gradient(to bottom, var(--dark-bg-deep), var(--dark-bg));
  padding: var(--section-pad);
  color: var(--white);
}
.sustainability-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 48px;
}
.sustainability-header h2 {
  font-size: clamp(32px, 4vw, 48px);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1px;
  max-width: 500px;
}
.sustainability-header p {
  font-size: 15px;
  color: oklch(100% 0 none / 0.5);
  max-width: 350px;
}
.sustainability-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.sustain-card {
  background: oklch(100% 0 none / 0.04);
  border: 1px solid oklch(100% 0 none / 0.08);
  border-radius: var(--radius);
  padding: 32px 24px;
  transition: all 0.3s;
}
.sustain-card:hover {
  background: oklch(100% 0 none / 0.08);
  border-color: oklch(81.03% 0.1356 198.40 / 0.3);
  transform: translateY(-4px);
}
.sustain-card-icon {
  width: 44px;
  height: 44px;
  background: oklch(81.03% 0.1356 198.40 / 0.15);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 20px;
  color: var(--accent);
}
.sustain-card h4 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 10px;
  line-height: 1.3;
}
.sustain-card p {
  font-size: 13px;
  color: oklch(100% 0 none / 0.5);
  line-height: 1.6;
}

