/* ===== SECTION DIVIDER ===== */
.section-divider {
  position: relative;
  height: 0;
  z-index: 2;
}
.section-divider::after {
  content: '';
  position: absolute;
  left: 80%;
  width: 1px;
  height: clamp(60px, 10vw, 150px);
  top: calc(clamp(60px, 10vw, 150px) * -0.6);
  background: white;
}
.section-divider:nth-of-type(even)::after {
  left: 20%;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.3s ease;
  text-transform: lowercase;
}
.btn:hover .arrow { transform: translateX(4px); }

.btn-primary {
  background: var(--accent);
  color: var(--dark);
}
.btn-primary:hover { background: var(--accent-light); }

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 1.5px solid var(--dark);
}
.btn-outline:hover { background: var(--dark); color: var(--white); }

.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 1.5px solid var(--white-30);
}
.btn-outline-light:hover { background: var(--white-10); }

/* ===== PLACEHOLDER IMAGES ===== */
.placeholder-img {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white-30);
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--radius);
  background: linear-gradient(135deg, oklch(28.16% 0.0340 255.80) 0%, oklch(35.31% 0.0349 248.85) 100%);
}

/* ===== TOP BAR ===== */
#topbar {
  background: var(--dark);
  border-bottom: 1px solid var(--white-06);
  padding: 10px 0;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 101;
}
.topbar-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: var(--white-50);
}
.topbar-left {
  display: flex;
  align-items: center;
  gap: 16px;
}
.topbar-socials {
  display: flex;
  gap: 12px;
}
.topbar-socials a {
  color: var(--white-50);
  font-size: 12px;
  font-weight: 600;
  transition: color 0.3s;
}
.topbar-socials a:hover { color: var(--white); }
.topbar-right {
  display: flex;
  align-items: center;
  gap: 24px;
}

/* ===== NAVBAR ===== */
#navbar {
  position: fixed;
  top: 38px;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 16px 0;
  transition: background 0.3s, backdrop-filter 0.3s, top 0.3s;
}
#navbar.scrolled {
  top: 0;
  background: linear-gradient(to left, var(--dark-bg-deep), var(--dark));
  backdrop-filter: blur(12px);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-flex;
  align-items: center;
}
.logo-img {
  height: 50px;
  width: auto;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 15px;
  font-weight: 500;
  color: var(--white-75);
  transition: color 0.3s;
  display: flex;
  align-items: center;
  gap: 5px;
}
.nav-links a:hover { color: var(--white); }
.nav-links svg { width: 10px; height: 10px; opacity: 0.6; }

