/* Contact Us */
.footer-contact {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}
.contact-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 14px;
  color: var(--white-60);
  line-height: 1.6;
}
.contact-item i {
  color: var(--accent);
  font-size: 14px;
  margin-top: 4px;
  flex-shrink: 0;
}
.contact-item a {
  color: var(--white-60);
  transition: color 0.3s;
}
.contact-item a:hover {
  color: var(--accent);
}

/* Social icons */
.footer-social {
  display: flex;
  gap: 12px;
}
.social-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: 1px solid var(--white-20);
  color: var(--white);
  font-size: 15px;
  transition: all 0.3s;
}
.social-icon:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--dark);
}

/* Bottom bar */
.footer-bottom {
  border-top: 1px solid var(--white-08);
  padding-top: 24px;
  text-align: center;
  font-size: 13px;
  color: var(--white-35);
}

/* ===== COMPONENT RESPONSIVE ===== */

/* ---- 1024px: Nav goes mobile, footer 1+3 ---- */
@media (max-width: 1024px) {
  .nav-links, .nav-actions { display: none; }
  .mobile-toggle { display: flex; }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
}

/* ---- 960px: Footer 2-col ---- */
@media (max-width: 960px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-col:last-child {
    grid-column: 1 / -1;
  }
}

/* ---- 768px: Hide topbar, shift navbar ---- */
@media (max-width: 768px) {
  #topbar { display: none; }
  #navbar { top: 0; }
}

/* ---- 600px: Footer single column ---- */
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: auto; }
  .footer-col:last-child { grid-column: auto; }
}

/* ===== HERO ===== */
#hero {
  padding: 180px 0 120px;
  color: var(--white);
  position: relative;
  overflow: hidden;
}
#hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url('/hero1.webp') center / cover no-repeat;
  filter: grayscale(1);
  z-index: 0;
  pointer-events: none;
}
#hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, oklch(from var(--overlay) l c h / 0.75) 0%, oklch(from var(--overlay) l c h / 0.55) 50%, oklch(from var(--overlay) l c h / 0.80) 100%);
  z-index: 1;
  pointer-events: none;
}

.hero-badge {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 32px;
}

.hero-title {
  font-size: clamp(48px, 8vw, 96px);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -2px;
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 18px;
  color: var(--white-60);
  max-width: 500px;
  margin: 0 0 40px;
  font-weight: 400;
}

.hero-ctas {
  display: flex;
  align-items: center;
  gap: 16px;
}

.hero-content {
  position: relative;
  z-index: 2;
}

/* ===== SERVICES CAROUSEL SECTION ===== */
#services {
  background: var(--cream);
  padding: var(--section-pad);
  color: var(--cobalt);
}

/* Header */
.sc-header {
  margin-bottom: 48px;
}
.sc-header h2 {
  color: var(--cobalt);
  max-width: 700px;
}

/* Tabs row */
.sc-tabs {
  display: flex;
  gap: 12px;
  margin-bottom: 32px;
}
.sc-tab {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 24px;
  border: none;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--dark-mid), var(--dark));
  color: var(--white);
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.35s ease;
}
.sc-tab i {
  font-size: 20px;
  color: var(--accent);
  transition: color 0.35s ease;
}
.sc-tab:hover {
  opacity: 0.9;
}
.sc-tab.active {
  background: linear-gradient(135deg, var(--accent), oklch(75% 0.14 198.40));
}
.sc-tab.active i {
  color: var(--white);
}

/* Content panel */
.sc-panel {
  display: grid;
  grid-template-columns: 2fr 3fr;
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 4px 24px oklch(0% 0 none / 0.08);
}

/* Panel image */
.sc-panel-img {
  min-height: 400px;
  overflow: hidden;
}

/* Panel body */
.sc-panel-body {
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.sc-panel-body h3 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 16px;
  line-height: 1.3;
  color: var(--cobalt);
}
.sc-panel-body p {
  font-size: 15px;
  color: var(--gray-600);
  line-height: 1.7;
  margin-bottom: 24px;
}

