/* ===== CTA PARTNER SECTION ===== */
#cta-partner {
  padding: var(--section-pad);
}
.cta-partner-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.cta-partner-img {
  height: 400px;
  border-radius: var(--radius);
  overflow: hidden;
}
.cta-partner-text h2 {
  font-size: clamp(32px, 4vw, 44px);
  color: var(--white);
  margin-bottom: 20px;
}
.cta-partner-text p {
  font-size: 15px;
  color: var(--white-55);
  line-height: 1.7;
  margin-bottom: 32px;
}

/* ===== HOME PAGE RESPONSIVE ===== */

/* ---- 1024px: Service panels stack ---- */
@media (max-width: 1024px) {
  .sc-tabs { flex-wrap: wrap; }
  .sc-tab { flex: 1 1 calc(50% - 6px); }
  .sc-panel { grid-template-columns: 1fr; }
  .sc-panel-img { min-height: 280px; }
  .sc-panel-body { padding: 32px; }
}

/* ---- 960px: Sectors sidebar stacks ---- */
@media (max-width: 960px) {
  .sector-sidebar { grid-template-columns: 1fr; }
  .sector-main { height: 60%; align-self: start; }
}

/* ---- 768px: Reduced hero, sectors 1-col, FAQ/CTA single col ---- */
@media (max-width: 768px) {
  #hero { padding-top: 140px; }

  .sectors-header { flex-direction: column; align-items: flex-start; gap: 16px; }
  .sectors-layout { grid-template-columns: 1fr; }
  .sector-main { height: 380px; align-self: auto; order: 2; }
  .sector-sidebar { order: 1; grid-template-columns: 1fr 1fr; }

  .faq-layout { grid-template-columns: 1fr; }
  .faq-img { max-height: 350px; margin-top: 0; }

  .cta-partner-inner { grid-template-columns: 1fr; }
}

/* ---- 600px: Service tabs stack, sectors sidebar 1-col ---- */
@media (max-width: 600px) {
  .sc-tabs { flex-direction: column; flex-wrap: nowrap; }
  .sc-tab { flex: 1 1 100%; }
  .sc-panel-img { min-height: 220px; }
  .sc-panel-body { padding: 24px; }

  .sector-sidebar { grid-template-columns: 1fr; }
}

/* ---- 460px: Hero CTAs stack ---- */
@media (max-width: 460px) {
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .hero-ctas .btn,
  .hero-ctas .text-link { text-align: center; }

