   118	componentManager.register('.testimonials-slider', (elements) => {
   119	    elements.forEach(slider => {
   120	        const testimonialWrappers = slider.querySelectorAll('.testimonial-wrapper');
   121	        const prevButton = slider.querySelector('.arrow.prev');
   122	        const nextButton = slider.querySelector('.arrow.next');
   123	        
   124	        if (testimonialWrappers.length <= 1) return;
   125	        
   126	        let currentTestimonialIndex = 0;
   127	        let testimonialInterval = null;
   128	        const rotationInterval = 6000;
   129	        let isTransitioning = false;
   130	        
   131	        function showTestimonial(index) {
   132	            if (isTransitioning || testimonialWrappers.length === 0) return;
   133	            
   134	            isTransitioning = true;
   135	            
   136	            const currentWrapper = testimonialWrappers[currentTestimonialIndex];
   137	            currentWrapper.style.opacity = '0';
   138	            currentWrapper.style.transform = 'translateY(-20px)';
   139	            
   140	            setTimeout(() => {
   141	                currentTestimonialIndex = index;
   142	                const newWrapper = testimonialWrappers[currentTestimonialIndex];
   143	                newWrapper.style.transform = 'translateY(20px)';
   144	                newWrapper.style.opacity = '1';
   145	                
   146	                setTimeout(() => {
   147	                    newWrapper.style.transform = 'translateY(0)';
   148	                    isTransitioning = false;
   149	                }, 50);
   150	            }, 500);
   151	        }
   152	        
   153	        function nextTestimonial() {
   154	            if (isTransitioning) return;
   155	            const nextIndex = (currentTestimonialIndex + 1) % testimonialWrappers.length;
   156	            showTestimonial(nextIndex);
   157	        }
   158	        
   159	        function previousTestimonial() {
   160	            if (isTransitioning) return;
   161	            const prevIndex = (currentTestimonialIndex - 1 + testimonialWrappers.length) % testimonialWrappers.length;
   162	            showTestimonial(prevIndex);
   163	        }
   164	        
   165	        function startAutoRotation() {
   166	            if (testimonialInterval) clearInterval(testimonialInterval);
   167	            testimonialInterval = setInterval(nextTestimonial, rotationInterval);
   168	        }
   169	        
   170	        function stopAutoRotation() {
   171	            if (testimonialInterval) {
   172	                clearInterval(testimonialInterval);
   173	                testimonialInterval = null;
   174	            }
   175	        }
   176	        
   177	        if (nextButton) {
   178	            nextButton.addEventListener('click', () => {
   179	                stopAutoRotation();
   180	                nextTestimonial();
   181	                setTimeout(startAutoRotation, 3000);
   182	            });
   183	        }
   184	        
   185	        if (prevButton) {
   186	            prevButton.addEventListener('click', () => {
   187	                stopAutoRotation();
   188	                previousTestimonial();
   189	                setTimeout(startAutoRotation, 3000);
   190	            });
   191	        }
   192	        
   193	        slider.addEventListener('mouseenter', stopAutoRotation);
   194	        slider.addEventListener('mouseleave', startAutoRotation);
   195	        
   196	        startAutoRotation();
   197	        
   198	        window.addEventListener('beforeunload', stopAutoRotation);
   199	    });
   200	});
