   277	// Image aspect ratio detection function
   278	function checkImageAspectRatio(modal) {
   279	    const image = modal.querySelector('.news-modal-image');
   280	    if (!image) return;
   281	    
   282	    // Remove any existing portrait-image class
   283	    modal.classList.remove('portrait-image');
   284	    
   285	    // Function to check aspect ratio once image is loaded
   286	    function checkRatio() {
   287	        const aspectRatio = image.naturalWidth / image.naturalHeight;
   288	        
   289	        // If aspect ratio is less than 0.7 (very tall/portrait), apply special layout
   290	        if (aspectRatio < 0.7) {
   291	            modal.classList.add('portrait-image');
   292	            console.log('Portrait image detected, applying vertical layout');
   293	        } else {
   294	            console.log('Landscape image detected, using side-by-side layout');
   295	        }
   296	    }
   297	    
   298	    // Check if image is already loaded
   299	    if (image.complete && image.naturalHeight !== 0) {
   300	        checkRatio();
   301	    } else {
   302	        // Wait for image to load
   303	        image.addEventListener('load', checkRatio);
   304	        
   305	        // Fallback timeout in case image fails to load
   306	        setTimeout(() => {
   307	            if (image.naturalHeight === 0) {
   308	                console.log('Image failed to load, using default layout');
   309	            }
   310	        }, 3000);
   311	    }
   312	}
