   349	// Modal utility functions
   350	function openModal(modal) {
   351	    modal.style.display = 'flex';
   352	    document.body.classList.add('modal-open');
   353	    
   354	    // Trigger reflow to ensure display change is applied
   355	    modal.offsetHeight;
   356	    
   357	    // Add active class for animation
   358	    modal.classList.add('active');
   359	    
   360	    // Focus management for accessibility
   361	    const firstFocusable = modal.querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
   362	    if (firstFocusable) {
   363	        firstFocusable.focus();
   364	    }
   365	    
   366	    // Store the previously focused element (store the actual element, not as a selector)
   367	    modal.previousFocusElement = document.activeElement;
   368	}
   369	
   370	function closeModal(modal) {
   371	    modal.classList.remove('active');
   372	    document.body.classList.remove('modal-open');
   373	    
   374	    // Wait for animation to complete before hiding
   375	    setTimeout(() => {
   376	        modal.style.display = 'none';
   377	        
   378	        // Restore focus to previously focused element
   379	        if (modal.previousFocusElement && modal.previousFocusElement.focus) {
   380	            modal.previousFocusElement.focus();
   381	        }
   382	    }, 300);
   383	}
