  --gold-light: #e8d5a0;
  --white: #ffffff;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-400: #9ca3af;
  --gray-600: #6b7280;
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 20px;
  --container: 1200px;
  --section-pad: 100px 0;
}

/* ===== UTILITIES ===== */
.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 24px;
}

.section-tag {
  display: inline-block;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
}

.arrow {
  display: inline-block;
  margin-left: 8px;
  transition: transform 0.3s;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: 50px;
  font-size: 14px;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  border: none;
  transition: all 0.3s ease;
  text-transform: lowercase;
}
.btn:hover .arrow { transform: translateX(4px); }

.btn-primary {
  background: var(--gold);
  color: var(--dark);
}
.btn-primary:hover { background: var(--gold-light); }

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 1.5px solid var(--dark);
}
.btn-outline:hover { background: var(--dark); color: var(--white); }

.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn-outline-light:hover { background: rgba(255,255,255,0.1); }

.btn-dark {
  background: var(--dark);
  color: var(--white);
}
.btn-dark:hover { background: #2a2a3e; }

.btn-white {
  background: var(--white);
  color: var(--dark);
}
.btn-white:hover { background: var(--gray-100); }

/* ===== PLACEHOLDER IMAGES ===== */
.placeholder-img {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.3);
  font-size: 14px;
  font-weight: 500;
  border-radius: var(--radius);
  background: linear-gradient(135deg, #1e2a3a 0%, #2d3d4d 100%);
}

/* ===== NAVBAR ===== */
#navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 16px 0;
  transition: background 0.3s, backdrop-filter 0.3s;
}
#navbar.scrolled {
  background: rgba(21, 21, 31, 0.95);
  backdrop-filter: blur(12px);
}
"}

