{"function": "() => {
  // Check if content-grid sections are rendering as grids
  const grids = document.querySelectorAll('.content-grid');
  return Array.from(grids).map(el => ({
    id: el.id || el.tagName,
    display: getComputedStyle(el).display,
    gridTemplateColumns: getComputedStyle(el).gridTemplateColumns
  }));
}"}

{"function": "() => {
  const breakouts = document.querySelectorAll('.breakout');
  return Array.from(breakouts).map(el => ({
    className: el.className,
    parentId: el.parentElement.id || el.parentElement.tagName,
    gridColumn: getComputedStyle(el).gridColumn,
    width: el.offsetWidth
  }));
}"}

{"function": "() => {
  // Check elements that should be in content column (not breakout, not full-width)
  const contentItems = [
    document.querySelector('.stats-header'),
    document.querySelector('.innovation-header'),
    document.querySelector('.cta-bottom-inner')
  ];
  return contentItems.map(el => ({
    className: el.className,
    gridColumn: getComputedStyle(el).gridColumn,
    width: el.offsetWidth,
    computedMaxWidth: getComputedStyle(el).maxWidth
  }));
}"}

