/* ------------------ Floating Popup ------------------ */
.floating-popup {
  position: fixed;
  bottom: 24px;
  right: 24px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: #fff;
  border-radius: 14px;
  z-index: 1000;
  animation: popupSlideIn 0.6s ease-out forwards;
  isolation: isolate;
  overflow: hidden;
}

/* Gradient border */
.floating-popup::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 2px; /* BORDER THICKNESS */
  border-radius: inherit;
  background: linear-gradient(90deg, #FF4006 0%, #FFE9EA 67%, #A37CFF 100%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  z-index: -1;
}

/* Lottie background layer */
.floating-popup .lottie-bg {
  position: absolute;
  z-index: 0;
  pointer-events: none;
  opacity: 0; /* invisible by default */
  transition: opacity 0.5s ease; /* smooth fade */
}

/* Keep all content above */
.floating-popup > * {
  position: relative;
  z-index: 1;
}

/* When hovering on floating popup, lottie becomes visible */
.floating-popup:hover .lottie-bg {
  opacity: 0.6; /* adjust intensity */
}

/* ------------------ Base buttons ------------------ */
.icon-btn {
  display: flex;
  align-items: center;
  height: 35px;
  border-radius: 10px;
  border: none;
  background: #fff;
  cursor: pointer;
  padding: 0;
  overflow: hidden;
  box-shadow: 0 12px 30px rgba(0,0,0,.2);
  transition: background 0.3s ease;
}

/* Icon */
.icon {
  width: 25px;
  height: 35px;
  display: grid;
  place-items: center;
  font-size: 18px;
  flex-shrink: 0;
}

/* ------------------ Expandable button ------------------ */
.expand-btn {
  display: flex;
  align-items: center;
  padding: 0 6px; /* spacing for text */
  overflow: hidden;
  background: #fff;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.3s ease;
}

.expand-btn .icon {
  flex-shrink: 0; /* icon fixed size */
}

.expand-btn .btn-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--icon-color);
  white-space: nowrap;
  opacity: 0;
  max-width: 0;
  overflow: hidden;
  transition: max-width 0.5s ease, opacity 0.5s ease;
}

/* Expanded state */
.expand-btn.expanded {
  background: #15151F;
  --icon-color: #fff;
}

.expand-btn.expanded .btn-text {
  max-width: 150px; /* only text expands, icon stays */
  opacity: 1;
  margin-right:10px;
}

.expand-btn.expanded .icon{
	width:35px;
}

/* R logo */
.r-logo {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  font-weight: 700;
  color: #0057ff;
  text-decoration: none;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 4px 19px rgba(0, 0, 0, 0.24);
  transition: background 0.5s ease;
}
.r-logo:hover{
	background: #15151F;
}

/* Plus button */
.plus-btn {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  background: #15151F;
  cursor: pointer;
  transition: transform 0.3s ease;
}

/* Plus icon */
.plus-icon {
  position: relative;
  width: 12px;
  height: 12px;
  transition: transform 0.3s ease;
}

.plus-icon::before,
.plus-icon::after {
  content: "";
  position: absolute;
  background: #fff;
  border-radius: 2px;
}

/* Vertical line */
.plus-icon::before {
  width: 2px;
  height: 100%;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
}

/* Horizontal line */
.plus-icon::after {
  width: 100%;
  height: 2px;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
}

/* Rotation */
.plus-btn.active .plus-icon {
  transform: rotate(45deg);
}

/* ------------------ Similar panel ------------------ */
.similar-panel {
  position: fixed;
  right: 24px;
  bottom: 100px;
  width: 340px;
  background: #E6E6E6;
  border-radius: 6px;
  box-shadow: 0px 10px 30px rgba(0, 0, 0, 0.3);
  transform: translateY(40px);
  opacity: 0;
  pointer-events: none;
  transition: transform 0.35s ease, opacity 0.35s ease;
  overflow: hidden;
  z-index: 999;
}

.similar-panel.open {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}

.panel-header {
  padding: 0px 9px;
  background: #111;
  color: #fff;
  font-size: 12px;
}

.panel-body {
  padding: 8px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.card {
  background: #fff;
  padding: 5px 5px 2px 5px;
  border-radius: 2px;
  display: flex;
  flex-direction: column;
  font-weight: 600;
  font-size: 8px;
  opacity: 1;
  transition: opacity 0.3s ease;
}

/* ------------------ Media ------------------ */
@media (max-width: 998px) {
