#services {
  background: linear-gradient(to bottom, var(--dark-bg-deep), var(--dark-bg));
  padding: var(--section-pad);
  color: var(--white);
}

/* Header */
.sc-header {
  margin-bottom: 48px;
}
.sc-header h2 {
  font-size: clamp(32px, 4vw, 48px);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -1px;
  color: var(--white);
  max-width: 700px;
}

/* Tabs row */
.sc-tabs {
  display: flex;
  gap: 12px;
  margin-bottom: 32px;
}
.sc-tab {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 24px;
  border: 1px solid oklch(100% 0 none / 0.08);
  border-radius: var(--radius);
  background: oklch(100% 0 none / 0.04);
  color: oklch(100% 0 none / 0.55);
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.35s ease;
}
.sc-tab i {
  font-size: 20px;
  color: oklch(100% 0 none / 0.35);
  transition: color 0.35s ease;
}
.sc-tab:hover {
  background: oklch(100% 0 none / 0.08);
  color: var(--white);
}
.sc-tab:hover i {
  color: var(--accent);
}
.sc-tab.active {
  background: oklch(81.03% 0.1356 198.40 / 0.15);
  border-color: oklch(81.03% 0.1356 198.40 / 0.3);
  color: var(--white);
}
.sc-tab.active i {
  color: var(--accent);
}

/* Content panel */
.sc-panel {
  display: grid;
  grid-template-columns: 2fr 3fr;
  gap: 40px;
  background: oklch(100% 0 none / 0.04);
  border: 1px solid oklch(100% 0 none / 0.08);
  border-radius: var(--radius);
  overflow: hidden;
}

/* Panel image */
.sc-panel-img {
  min-height: 400px;
  overflow: hidden;
}
.sc-panel-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Panel body */
.sc-panel-body {
  padding: 48px 48px 48px 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.sc-panel-body h3 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 16px;
  line-height: 1.3;
}
.sc-panel-body p {
  font-size: 15px;
  color: oklch(100% 0 none / 0.65);
  line-height: 1.7;
  margin-bottom: 24px;
}

/* Check list */
.check-list {
  list-style: none;
  padding: 0;
  margin: 0 0 32px 0;
}
.check-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  font-size: 15px;
  color: oklch(100% 0 none / 0.8);
  border-bottom: 1px solid oklch(100% 0 none / 0.06);
}
.check-list li:last-child {
  border-bottom: none;
}
.check-list li i {
  color: var(--accent);
  font-size: 14px;
  flex-shrink: 0;
}

/* Panel transitions */
.sc-enter {
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.sc-enter-start {
  opacity: 0;
  transform: translateY(12px);
}
.sc-enter-end {
  opacity: 1;
  transform: translateY(0);
