#footer {
  background: linear-gradient(135deg, var(--dark-bg-deep), var(--dark) 60%, oklch(38% 0.12 253.58));
  padding: 64px 0 32px;
  color: var(--white);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1fr 1.4fr 1.2fr;
  gap: 60px;
  margin-bottom: 48px;
}

/* Column headings */
.footer-col h4 {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--accent);
  color: var(--white);
}

/* Quick Links */
.footer-links {
  display: flex;
  flex-direction: column;
}
.footer-links a {
  display: block;
  font-size: 14px;
  color: oklch(100% 0 none / 0.6);
  padding: 10px 16px;
  border-left: 2px solid oklch(100% 0 none / 0.1);
  transition: all 0.3s;
}
.footer-links a:hover {
  color: var(--white);
  border-left-color: var(--accent);
}

/* Opening Hours */
.footer-hours {
  display: flex;
  flex-direction: column;
}
