{"function": "() => {
  const heroTitle = document.querySelector('.hero-title');
  const breakoutFirst = document.querySelector('.breakout');
  // Get the first child text element of the breakout
  const breakoutHeading = breakoutFirst.querySelector('h2') || breakoutFirst.querySelector('h3') || breakoutFirst.firstElementChild;
  return {
    viewportWidth: window.innerWidth,
    heroTitleLeft: Math.round(heroTitle.getBoundingClientRect().left),
