  };
}"}

{"function": "() => {
  const heroTitle = document.querySelector('.hero-title');
  const heroContent = document.querySelector('.hero-content');
  const hero = document.getElementById('hero');

  // Find a breakout section heading
  const sections = document.querySelectorAll('.content-grid');
  let breakoutH2Left = null;
  let breakoutElLeft = null;
  for (const s of sections) {
    const bo = s.querySelector('.breakout');
    if (bo) {
      breakoutElLeft = Math.round(bo.getBoundingClientRect().left);
      const h = bo.querySelector('h2, h3');
      if (h) {
        breakoutH2Left = Math.round(h.getBoundingClientRect().left);
        break;
      }
    }
  }

  return {
    viewportWidth: window.innerWidth,
    heroLeft: Math.round(hero.getBoundingClientRect().left),
    heroContentLeft: Math.round(heroContent.getBoundingClientRect().left),
    heroTitleLeft: Math.round(heroTitle.getBoundingClientRect().left),
    breakoutElLeft,
    breakoutH2Left,
    titleVsH2Diff: breakoutH2Left !== null ? Math.round(heroTitle.getBoundingClientRect().left - breakoutH2Left) : null
  };
}"}

