{"function": "() => {
  const logo = document.querySelector('.nav-container > a');
  const topbarLeft = document.querySelector('.topbar-left');
  const heroTitle = document.querySelector('.hero-title');
  const breakout = document.querySelector('#services .breakout');

  const logoRect = logo.getBoundingClientRect();
  const topbarRect = topbarLeft.getBoundingClientRect();
  const heroRect = heroTitle.getBoundingClientRect();
  const breakoutRect = breakout.getBoundingClientRect();

  // Also check right edges
  const navActions = document.querySelector('.nav-actions');
  const navActionsRect = navActions ? navActions.getBoundingClientRect() : null;

  return {
    viewportWidth: window.innerWidth,
    left: {
      topbar: Math.round(topbarRect.left),
      logo: Math.round(logoRect.left),
      heroTitle: Math.round(heroRect.left),
      breakout: Math.round(breakoutRect.left),
      diffTopbar: Math.round(topbarRect.left - breakoutRect.left),
      diffLogo: Math.round(logoRect.left - breakoutRect.left),
      diffHero: Math.round(heroRect.left - breakoutRect.left)
    },
    right: {
      navActions: navActionsRect ? Math.round(navActionsRect.right) : null,
      breakout: Math.round(breakoutRect.right),
      diffNavActions: navActionsRect ? Math.round(breakoutRect.right - navActionsRect.right) : null
    }
  };
}"}

