**Current Responsive Rules** (lines 1025-1118):
```css
/* ---- 1024px: Nav goes mobile, service panels stack, footer 1+3 ---- */
@media (max-width: 1024px) {
  .nav-links, .nav-actions { display: none; }
  .mobile-toggle { display: flex; }
  .sc-tabs { flex-wrap: wrap; }
  .sc-tab { flex: 1 1 calc(50% - 6px); }
  .sc-panel { grid-template-columns: 1fr; }
  .sc-panel-img { min-height: 280px; }
  .sc-panel-body { padding: 32px; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
}

/* ---- 960px: Sectors sidebar stacks, footer 1+2+1, sector-main 60% height ---- */
@media (max-width: 960px) {
  /* Sectors: keep 2-col layout, but sidebar cards stack, main card fixed height */
  .sector-sidebar { grid-template-columns: 1fr; }
  .sector-main { height: 60%; align-self: start; }

  /* Footer: brand row, 2 cols, contact full width */
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-brand { grid-column: 1 / -1; }
  .footer-col:last-child { grid-column: 1 / -1; }
}

/* ---- 768px: Reduced padding, topbar hidden, sectors 1-col, sector order swap ---- */
@media (max-width: 768px) {
  :root { --section-pad: 100px 0; }

  /* Hide topbar, shift navbar up, reduce hero top padding to compensate */
  #topbar { display: none; }
  #navbar { top: 0; }
  #hero { padding-top: 140px; }

  /* Sectors: 1 column, sidebar back to 2-col grid, reset main card height, swap order */
  .sectors-header { flex-direction: column; align-items: flex-start; gap: 16px; }
  .sectors-layout { grid-template-columns: 1fr; }
  .sector-main { height: 380px; align-self: auto; order: 2; }
  .sector-sidebar { order: 1; }
  .sector-sidebar { grid-template-columns: 1fr 1fr; }

  /* FAQ: single column, image below */
  .faq-layout { grid-template-columns: 1fr; }
  .faq-img { max-height: 350px; }

  /* CTA partner: single column */
  .cta-partner-inner { grid-template-columns: 1fr; }
}

/* ---- 600px: Service tabs stack, footer single column, sectors sidebar 1-col ---- */
@media (max-width: 600px) {
  .sc-tabs { flex-direction: column; flex-wrap: nowrap; }
  .sc-tab { flex: 1 1 100%; }
  .sc-tab span { display: inline; }
  .sc-panel-img { min-height: 220px; }
  .sc-panel-body { padding: 24px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: auto; }
  .footer-col:last-child { grid-column: auto; }
  .sector-sidebar { grid-template-columns: 1fr; }
}

/* ---- 480px: Tighten padding ---- */
@media (max-width: 480px) {
  :root { --padding-inline: 1.5rem; }
}

/* ---- 460px: Hero CTAs stack ---- */
@media (max-width: 460px) {
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .hero-ctas .btn,
  .hero-ctas .text-link { text-align: center; }
}
```

