  font-weight: 500;
  border-radius: var(--radius);
  background: linear-gradient(135deg, oklch(28.16% 0.0340 255.80) 0%, oklch(35.31% 0.0349 248.85) 100%);
}

/* ===== TOP BAR ===== */
#topbar {
  background: var(--dark);
  border-bottom: 1px solid var(--white-06);
  padding: 10px 0;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 101;
}
.topbar-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: var(--white-50);
}
.topbar-left {
  display: flex;
  align-items: center;
  gap: 16px;
}
.topbar-socials {
  display: flex;
  gap: 12px;
}
.topbar-socials a {
  color: var(--white-50);
  font-size: 12px;
