  top: 0;
  background: linear-gradient(to left, var(--dark-bg-deep), var(--dark));
  backdrop-filter: blur(12px);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-flex;
  align-items: center;
}
