}
.sc-panel.is-animating .sc-panel-body .sc-cta {
  animation: scFadeIn 0.4s var(--ease-out-expo) forwards;
  animation-delay: calc(0.45s + var(--li-total, 6) * 0.1s + 0.15s);
}

/* Panel CTA link — overrides .arrow-link */
.sc-cta {
  font-size: 15px;
  color: var(--dark);
  align-self: flex-end;
}
.sc-cta:hover {
  color: var(--accent);
}"}

